{
  "implementation": "def solve(case):
    nodes = case['nodes']
    core = case['core_distance']
    dist_list = case['distances']
    n = len(nodes)

    dist_map = {}
    for u, v, d in dist_list:
        key = tuple(sorted([u, v]))
        dist_map[key] = d

    edges = []
    for i in range(n):
        for j in range(i + 1, n):
            u = nodes[i]
            v = nodes[j]
            d = dist_map[(u, v)]
            mr = max(core[u], core[v], d)
            edges.append((mr, u, v))

    edges.sort(key=lambda x: (x[0], x[1], x[2]))

    parent = {node: node for node in nodes}
    rank = {node: 0 for node in nodes}

    def find(x):
        while parent[x] != x:
            parent[x] = parent[parent[x]]
            x = parent[x]
        return x

    def union(x, y):
        rx, ry = find(x), find(y)
        if rx == ry:
            return False
        if rank[rx] < rank[ry]:
            parent[rx] = ry
        elif rank[rx] > rank[ry]:
            parent[ry] = rx
        else:
            parent[ry] = rx
            rank[rx] += 1
        return True

    mst_edges = []
    total_weight = 0.0
    for w, u, v in edges:
        if union(u, v):
            mst_edges.append([u, v, w])
            total_weight += w
            if len(mst_edges) == n - 1:
                break

    return {"mst_edges": mst_edges, "total_weight": total_weight}"
}
